 if(document.hidden && round.active){ round.pausedAt=performance.now(); }
 else if(!document.hidden && round.active && round.pausedAt){ round.endsAt += performance.now()-round.pausedAt; round.pausedAt=0; lastTime=performance.now(); }
});
```
